import {ActionList, ActionMenu} from '@primer/react'
import {RuleSeverityFilterOption, severityOptions} from '../types/rule-severity-filter'
import {RuleCategoryFilterOption, ruleCategoryOptions} from '../types/rule-category'
import {
  languageOptions,
  mapRuleLanguageFilterOptionToRuleLanguage,
  RuleLanguageFilterOption,
} from '../types/rule-language'
import {RuleLanguageLabel} from './RuleLanguageLabel'
import styles from './RuleGroupFilters.module.css'

export interface RuleGroupFiltersProps {
  ruleCount: number
  selectedSeverity: RuleSeverityFilterOption
  selectedCategory: RuleCategoryFilterOption
  selectedLanguage: RuleLanguageFilterOption
  onSelectSeverity: (severity: RuleSeverityFilterOption) => void
  onSelectCategory: (category: RuleCategoryFilterOption) => void
  onSelectLanguage: (language: RuleLanguageFilterOption) => void
}

export function RuleGroupFilters({
  ruleCount,
  selectedSeverity,
  selectedCategory,
  selectedLanguage,
  onSelectSeverity,
  onSelectCategory,
  onSelectLanguage,
}: RuleGroupFiltersProps) {
  return (
    <div className={styles.container}>
      <div className={styles.titleSection}>
        <h3 className={styles.title}>
          <span>{ruleCount}</span> <span>{ruleCount === 1 ? 'rule' : 'rules'}</span>
        </h3>
      </div>

      <div className={styles.filtersSection}>
        <div className={styles.filterGroup}>
          <ActionMenu>
            <ActionMenu.Button className={styles.filterButton}>
              <div className={styles.filterButtonLabel}>{`Severity:`}</div>
              <span className={styles.filterButtonValue}>{selectedSeverity}</span>
            </ActionMenu.Button>
            <ActionMenu.Overlay width="auto">
              <ActionList selectionVariant="single">
                {severityOptions.map(option => (
                  <ActionList.Item
                    key={`severity-${option}`}
                    data-testid={`severity-option-${option.toLocaleLowerCase()}`}
                    selected={option === selectedSeverity}
                    onSelect={() => onSelectSeverity(option)}
                  >
                    {option}
                  </ActionList.Item>
                ))}
              </ActionList>
            </ActionMenu.Overlay>
          </ActionMenu>
        </div>

        <div className={styles.filterGroup}>
          <ActionMenu>
            <ActionMenu.Button className={styles.filterButton}>
              <div className={styles.filterButtonLabel}>{`Category:`}</div>
              <span className={styles.filterButtonValue}>{selectedCategory}</span>
            </ActionMenu.Button>
            <ActionMenu.Overlay width="auto">
              <ActionList selectionVariant="single">
                {ruleCategoryOptions.map(option => (
                  <ActionList.Item
                    key={`category-${option}`}
                    data-testid={`category-option-${option.toLowerCase()}`}
                    selected={option === selectedCategory}
                    onSelect={() => onSelectCategory(option)}
                  >
                    {option}
                  </ActionList.Item>
                ))}
              </ActionList>
            </ActionMenu.Overlay>
          </ActionMenu>
        </div>

        <div className={styles.filterGroup}>
          <ActionMenu>
            <ActionMenu.Button className={styles.filterButton}>
              <div className={styles.filterButtonLabel}>{`Language:`}</div>
              <span className={styles.filterButtonValue}>{selectedLanguage}</span>
            </ActionMenu.Button>
            <ActionMenu.Overlay width="auto">
              <ActionList selectionVariant="single">
                {languageOptions.map(option => {
                  const ruleLanguage = mapRuleLanguageFilterOptionToRuleLanguage(option)

                  return (
                    <ActionList.Item
                      key={`language-${option}`}
                      data-testid={`language-option-${option.toLowerCase()}`}
                      selected={option === selectedLanguage}
                      onSelect={() => onSelectLanguage(option)}
                    >
                      {ruleLanguage ? <RuleLanguageLabel language={ruleLanguage} /> : 'All'}
                    </ActionList.Item>
                  )
                })}
              </ActionList>
            </ActionMenu.Overlay>
          </ActionMenu>
        </div>
      </div>
    </div>
  )
}

try{ RuleGroupFilters.displayName ||= 'RuleGroupFilters' } catch {}