import DataCard from '@github-ui/data-card'
import {Grade, gradeToText} from '../types/grade'
import type {CodeQualityDocsUrls} from '../types/code-quality-docs-urls'
import {Link, ProgressBar} from '@primer/react'
import styles from './Metric.module.css'

export interface MetricProps {
  title: string
  data?: {
    grade: Grade
    findingsCount: number
  }
  codeQualityDocsUrls: CodeQualityDocsUrls
}

export function Metric({title, data, codeQualityDocsUrls}: MetricProps) {
  const findingsCount = data?.findingsCount || 0

  return (
    <DataCard className={styles.DataCard}>
      <h3 className={styles.CustomHeading}>{title}</h3>
      <p className={styles.GradeText}>{data ? gradeToText[data.grade] : 'No data'}</p>
      <MetricProgressBar grade={data ? data.grade : undefined} />
      <DataCard.Description className={styles.CustomDescription}>
        <span>
          {findingsCount} findings.
          {data && (
            <>
              {' '}
              <Link href={codeQualityDocsUrls.metrics} target="_blank" inline>
                Learn how this score is calculated.
              </Link>
            </>
          )}
        </span>
      </DataCard.Description>
    </DataCard>
  )
}

function MetricProgressBar({grade}: {grade?: Grade}) {
  const getColors = (g?: Grade) => {
    switch (g) {
      case Grade.A:
        return {activeColor: 'success.emphasis', activeCount: 4}
      case Grade.B:
        return {activeColor: 'attention.emphasis', activeCount: 3}
      case Grade.C:
        return {activeColor: 'severe.emphasis', activeCount: 2}
      case Grade.D:
        return {activeColor: 'danger.emphasis', activeCount: 1}
      default:
        return {activeColor: 'neutral.muted', activeCount: 0}
    }
  }

  const {activeColor, activeCount} = getColors(grade)
  const totalSegments = 4
  const progressPerSegment = 100 / totalSegments

  return (
    <ProgressBar barSize="small" className={styles.ProgressBar} aria-label={`Code quality grade: ${grade}`}>
      {Array.from({length: totalSegments}, (_, i) => (
        <ProgressBar.Item
          key={i}
          bg={i < activeCount ? activeColor : 'neutral.muted'}
          progress={progressPerSegment}
          aria-label={i < activeCount ? 'Progress segment' : 'Inactive segment'}
          aria-valuenow={progressPerSegment}
        />
      ))}
    </ProgressBar>
  )
}

try{ Metric.displayName ||= 'Metric' } catch {}
try{ MetricProgressBar.displayName ||= 'MetricProgressBar' } catch {}