import {FileIcon} from '@primer/octicons-react'
import {NestedListItemLeadingContent} from '@github-ui/nested-list-view/NestedListItemLeadingContent'
import {NestedListItemLeadingVisual} from '@github-ui/nested-list-view/NestedListItemLeadingVisual'
import {NestedListItemTitle} from '@github-ui/nested-list-view/NestedListItemTitle'
import {NestedListItem} from '@github-ui/nested-list-view/NestedListItem'
import type {RuleFile} from '../types/rule-file'
import {CounterLabel} from '@primer/react'

import styles from './RuleFileListItem.module.css'

export type RuleFileListItemProps = {
  file: RuleFile
}

export function RuleFileListItem({file}: RuleFileListItemProps) {
  return (
    <NestedListItem
      title={
        <NestedListItemTitle
          value={file.filePath}
          containerClassName={styles.content}
          anchorClassName={styles.link}
          trailingBadges={
            file.findingsCount > 1 ? [<CounterLabel key="counter">{file.findingsCount}</CounterLabel>] : []
          }
        />
      }
    >
      <NestedListItemLeadingContent className={styles.content}>
        <NestedListItemLeadingVisual icon={FileIcon} description="File" color="fg.muted" />
      </NestedListItemLeadingContent>
    </NestedListItem>
  )
}

try{ RuleFileListItem.displayName ||= 'RuleFileListItem' } catch {}