import {parseCursor, serializeCursor, type Cursor} from '@github-ui/code-scanning-shared/types/cursor'
import {useSearchParams} from '@github-ui/react-router'
import {useState} from 'react'
import {type RuleSeverityFilterOption, parseSeverity} from '../types/rule-severity-filter'
import type {RuleCategoryFilterOption} from '../types/rule-category'
import {parseRuleCategory} from '../types/rule-category'
import {mapLanguageStringToRuleLanguageFilterOption, type RuleLanguageFilterOption} from '../types/rule-language'

export function useRulesGroupsParams() {
  const [params, setParams] = useSearchParams()
  const [selectedSeverity, setSelectedSeverity] = useState<RuleSeverityFilterOption>(() =>
    parseSeverity(params.get('severity')),
  )
  const [selectedCategory, setSelectedCategory] = useState<RuleCategoryFilterOption>(() =>
    parseRuleCategory(params.get('category')),
  )
  const [selectedLanguage, setSelectedLanguage] = useState<RuleLanguageFilterOption>(() =>
    mapLanguageStringToRuleLanguageFilterOption(params.get('language')),
  )
  const [cursor, setCursor] = useState<Cursor | null>(() => parseCursor(params))

  const onSelectSeverity = (severity: RuleSeverityFilterOption) => {
    setSelectedSeverity(severity)
    setCursor(null)
    setParams(prevParams => {
      const next = new URLSearchParams(prevParams)
      next.set('severity', severity.toLowerCase())
      next.delete('before')
      next.delete('after')
      return next
    })
  }

  const onSelectCategory = (category: RuleCategoryFilterOption) => {
    setSelectedCategory(category)
    setCursor(null)
    setParams(prevParams => {
      const next = new URLSearchParams(prevParams)
      next.set('category', category.toLowerCase())
      next.delete('before')
      next.delete('after')
      return next
    })
  }

  const onSelectLanguage = (language: RuleLanguageFilterOption) => {
    setSelectedLanguage(language)
    setCursor(null)
    setParams(prevParams => {
      const next = new URLSearchParams(prevParams)
      next.set('language', language.toLowerCase())
      next.delete('before')
      next.delete('after')
      return next
    })
  }

  const onCursorChange = (newCursor: Cursor | null) => {
    setCursor(newCursor)
    setParams(prevParams => {
      const next = new URLSearchParams(prevParams)
      serializeCursor(newCursor, next)
      return next
    })
  }

  return {
    selectedSeverity,
    selectedCategory,
    selectedLanguage,
    cursor,
    onSelectSeverity,
    onSelectCategory,
    onSelectLanguage,
    onCursorChange,
  }
}
