import {ListItem} from '@github-ui/list-view/ListItem'
import {ListItemTitle} from '@github-ui/list-view/ListItemTitle'
import {CounterLabel, IconButton} from '@primer/react'
import type {RuleGroup} from '../types/rule-group'
import {ListItemLeadingContent} from '@github-ui/list-view/ListItemLeadingContent'
import {ChevronDownIcon, ChevronRightIcon} from '@primer/octicons-react'
import {useCallback} from 'react'
import {ListItemMetadata} from '@github-ui/list-view/ListItemMetadata'
import {RuleCategoryBadge} from './RuleCategoryBadge'
import {FindingSeverityBadge} from '../components/FindingSeverityBadge'
import {codeQualityShowPath} from '@github-ui/paths'
import {ListItemTrailingBadge} from '@github-ui/list-view/ListItemTrailingBadge'
import {RuleLanguageLabel} from './RuleLanguageLabel'
import styles from './RuleGroupListItem.module.css'

export interface RuleGroupListItemProps {
  owner: string
  repo: string
  group: RuleGroup
  expanded: boolean
  onExpandedChange?: (group: string) => void
  renderGroup: (group: RuleGroup) => React.ReactNode
}

export function RuleGroupListItem({
  owner,
  repo,
  group,
  expanded,
  onExpandedChange,
  renderGroup,
}: RuleGroupListItemProps) {
  const onToggle = useCallback(() => {
    onExpandedChange?.(group.ruleId)
  }, [onExpandedChange, group.ruleId])

  const toggleOnKeyDown = (event: React.KeyboardEvent) => {
    // eslint-disable-next-line @github-ui/ui-commands/no-manual-shortcut-logic
    if ((event.key === 'ArrowLeft' && expanded) || (event.key === 'ArrowRight' && !expanded)) {
      onToggle()
    }
  }

  return (
    <>
      <ListItem
        title={
          <ListItemTitle
            value={group.title}
            href={codeQualityShowPath({owner, repo, ruleId: group.ruleId})}
            trailingBadges={[
              <CounterLabel key="findings-count" className="ml-2 fgColor-muted">
                {group.findingsCount}
              </CounterLabel>,
              <ListItemTrailingBadge key="language-label" containerClassName="ml-2" title="Rule language label">
                <RuleCategoryBadge category={group.category} />
              </ListItemTrailingBadge>,
            ]}
            containerClassName={styles.titleContainer}
            headingClassName={styles.title}
          />
        }
        className={styles.container}
        metadata={
          <ListItemMetadata className="gap-2">
            <FindingSeverityBadge severity={group.severity} />
            <RuleLanguageLabel language={group.language} />
          </ListItemMetadata>
        }
      >
        <ListItemLeadingContent className={styles.leadingContent}>
          <IconButton
            aria-label={`Toggle ${group.title}`}
            icon={expanded ? ChevronDownIcon : ChevronRightIcon}
            variant="invisible"
            size="medium"
            onClick={onToggle}
            onKeyDown={toggleOnKeyDown}
            className={styles.iconButton}
          />
        </ListItemLeadingContent>
      </ListItem>
      {expanded && renderGroup(group)}
    </>
  )
}

try{ RuleGroupListItem.displayName ||= 'RuleGroupListItem' } catch {}