import {useCallback, useState} from 'react'
import type {RuleGroup} from '../types/rule-group'
import {ListView} from '@github-ui/list-view'
import {RuleGroupListItem} from './RuleGroupListItem'
import {RuleFilesListContainer} from './RuleFilesListContainer'
import {useRuleGroupsQuery} from '../hooks/use-rule-groups-query'
import {PrevNextPagination} from '@github-ui/code-scanning-shared/components/PrevNextPagination'
import styles from './RuleGroupList.module.css'
import {RowsLoading} from './RowsLoading'
import {ErrorState} from './ErrorState'
import {useRulesGroupsParams} from '../hooks/use-rule-groups-params'
import {codeQualityRulesPath} from '@github-ui/paths'
import {RuleSeverityFilterOption} from '../types/rule-severity-filter'
import {RuleCategoryFilterOption} from '../types/rule-category'
import {Blankslate} from '@primer/react/experimental'
import {BlankslateListItem} from './BlankslateListItem'
import {mapRuleLanguageFilterOptionToRuleLanguage, RuleLanguageFilterOption} from '../types/rule-language'
import {RuleGroupFilters} from './RuleGroupFilters'

export interface RuleGroupListProps {
  owner: string
  repo: string
  findingsCount: number
}

export function RuleGroupList({owner, repo, findingsCount}: RuleGroupListProps) {
  const [isExpanded, setIsExpanded] = useState<{[key: string]: boolean}>({})

  const {
    selectedSeverity,
    selectedCategory,
    selectedLanguage,
    cursor,
    onSelectCategory,
    onSelectSeverity,
    onSelectLanguage,
    onCursorChange,
  } = useRulesGroupsParams()
  const parsedRuleLanguageFilterOption = mapRuleLanguageFilterOptionToRuleLanguage(selectedLanguage)
  const rulesPath = codeQualityRulesPath({
    owner,
    repo,
    category: selectedCategory === RuleCategoryFilterOption.All ? undefined : selectedCategory.toLowerCase(),
    severity: selectedSeverity === RuleSeverityFilterOption.All ? undefined : selectedSeverity.toLowerCase(),
    language:
      selectedLanguage === RuleLanguageFilterOption.All || !parsedRuleLanguageFilterOption
        ? undefined
        : parsedRuleLanguageFilterOption.toLowerCase(),
  })

  const {data, isPending, isError} = useRuleGroupsQuery(rulesPath, {cursor})

  const toggleExpanded = useCallback(
    (expandedGroup: string) => {
      setIsExpanded(prev => ({
        ...prev,
        [expandedGroup]: !prev[expandedGroup],
      }))
    },
    [setIsExpanded],
  )

  // For now we're just going to show loading and error states
  // but in the future we'll handle this better.
  if (isPending) {
    return (
      <div className="border rounded-2">
        <RowsLoading rowCount={5} />
      </div>
    )
  }
  if (isError) {
    return <ErrorState message="Rules data could not be loaded right now." />
  }

  const groups = data?.rules || []
  const ruleCount = data?.count || 0

  return (
    <>
      <div className={styles.container}>
        <RuleGroupFilters
          ruleCount={ruleCount}
          selectedSeverity={selectedSeverity}
          selectedCategory={selectedCategory}
          selectedLanguage={selectedLanguage}
          onSelectSeverity={onSelectSeverity}
          onSelectCategory={onSelectCategory}
          onSelectLanguage={onSelectLanguage}
        />
        <ListView title="Findings" titleHeaderTag="h3" totalCount={findingsCount} className={styles.listView}>
          {ruleCount === 0 && (
            <BlankslateListItem className="rounded-2">
              <Blankslate.Heading>No findings available.</Blankslate.Heading>
              <Blankslate.Description>
                The last scan doesn&apos;t have code quality findings that match your filter criteria.
              </Blankslate.Description>
            </BlankslateListItem>
          )}
          {ruleCount > 0 &&
            groups.map((ruleGroup: RuleGroup) => (
              <RuleGroupListItem
                owner={owner}
                repo={repo}
                key={ruleGroup.ruleId}
                group={ruleGroup}
                expanded={isExpanded[ruleGroup.ruleId] || false}
                onExpandedChange={toggleExpanded}
                renderGroup={(rg: RuleGroup) => <RuleFilesListContainer owner={owner} repo={repo} rule={rg} />}
              />
            ))}
        </ListView>
      </div>
      <PrevNextPagination onCursorChange={onCursorChange} prevCursor={data?.prevCursor} nextCursor={data?.nextCursor} />
    </>
  )
}

try{ RuleGroupList.displayName ||= 'RuleGroupList' } catch {}