import {NestedListItem} from '@github-ui/nested-list-view/NestedListItem'

import {Link} from '@primer/react'
import {codeQualityShowPath} from '@github-ui/paths'
import styles from './RuleFileListMoreItem.module.css'

export type RuleFileListMoreItemProps = {
  owner: string
  repo: string
  ruleId: string
  remainingFindingsCount: number
}

export function RuleFileListMoreItem({owner, repo, ruleId, remainingFindingsCount}: RuleFileListMoreItemProps) {
  return (
    <NestedListItem
      title={
        <Link href={codeQualityShowPath({owner, repo, ruleId})} className={styles.link}>
          {remainingFindingsCount > 1 ? `and ${remainingFindingsCount} more findings` : 'and 1 more finding'}
        </Link>
      }
    />
  )
}

try{ RuleFileListMoreItem.displayName ||= 'RuleFileListMoreItem' } catch {}